package images

import (
	"slices"
	"time"

	ai "github.com/Kludex/pydantic-ai-go/ai"
)

// GeneratedImage contains one generated image and its provider metadata.
type GeneratedImage struct {
	// Content contains detached generated bytes and their media type.
	Content ai.BinaryContent
	// RevisedPrompt contains a provider-rewritten prompt when available.
	RevisedPrompt string
	// OutputFormat identifies the format resolved from the returned content.
	OutputFormat string
	// ProviderDetails contains detached provider-specific metadata for this image.
	ProviderDetails map[string]any
}

// Clone returns a detached generated image.
func (image GeneratedImage) Clone() GeneratedImage {
	image.Content.Data = slices.Clone(image.Content.Data)
	image.Content.VendorMetadata = cloneMap(image.Content.VendorMetadata)
	image.ProviderDetails = cloneMap(image.ProviderDetails)
	return image
}

// Result contains generated images and request metadata.
type Result struct {
	// Images contains at least one image when a model request succeeds.
	Images []GeneratedImage
	// Prompt is the original generation prompt.
	Prompt string
	// ModelName identifies the model that generated the images.
	ModelName string
	// ProviderName identifies the provider that served the request.
	ProviderName string
	// ProviderURL identifies the configured provider endpoint.
	ProviderURL string
	// Timestamp records when the response was decoded.
	Timestamp time.Time
	// Usage contains request, token, and cost accounting.
	Usage ai.Usage
	// ProviderDetails contains detached provider-specific response metadata.
	ProviderDetails map[string]any
	// ProviderResponseID contains the provider response identifier when available.
	ProviderResponseID string
	// Warnings describes settings the provider ignored or replaced.
	Warnings []string
}

// Clone returns a detached result.
func (result Result) Clone() Result {
	result.Images = cloneGeneratedImages(result.Images)
	result.Usage = result.Usage.Clone()
	result.ProviderDetails = cloneMap(result.ProviderDetails)
	result.Warnings = slices.Clone(result.Warnings)
	return result
}

// Image returns a detached copy of the first generated image.
func (result Result) Image() ai.BinaryContent {
	if len(result.Images) == 0 {
		return ai.BinaryContent{}
	}
	return result.Images[0].Clone().Content
}

// Price calculates the result price using the current genai-prices snapshot.
func (result Result) Price() (ai.PriceCalculation, error) {
	response := ai.ModelResponse{
		ModelName: result.ModelName, ProviderName: result.ProviderName, ProviderURL: result.ProviderURL,
		Timestamp: result.Timestamp, Usage: result.Usage.Clone(),
	}
	return response.Price()
}

func cloneResult(result *Result) *Result {
	cloned := result.Clone()
	return &cloned
}

func cloneGeneratedImages(value []GeneratedImage) []GeneratedImage {
	if value == nil {
		return nil
	}
	cloned := make([]GeneratedImage, len(value))
	for index, image := range value {
		cloned[index] = image.Clone()
	}
	return cloned
}
